// Pseudo-code: verify token by kid
function verifyAndIssue(idToken, tenantId){
  const kid = idToken.header.kid;
  const key = keyCache.get(tenantId, kid);
  if(!key) throw new Error("Unknown key");
  const payload = verifyJWT(idToken, key, {alg: key.alg, iss: tenantIss(tenantId)});
  const internal = signJWT({sub: payload.sub, tenant: tenantId, scopes: payload.scopes}, internalKey);
  return internal;
